// Should show success or rate limit warning toast
cy.get('.toast-container', {
  timeout: 10000
}).should('be.visible').and($toast => {
  const text = $toast.text();
  expect(text).to.match(/Your message has been sent to Satheesh|submitted a message recently/);
});

